PARAMS = {"length": {"value": 140.0, "unit": "mm", "provenance": "measured", "evidence": "TOP VIEW and FRONT VIEW overall dimension 140.0"}, "width": {"value": 40.0, "unit": "mm", "provenance": "measured", "evidence": "TOP VIEW and RIGHT VIEW overall dimension 40.0"}, "height": {"value": 70.0, "unit": "mm", "provenance": "measured", "evidence": "RIGHT VIEW dimension 70.0, FRONT VIEW 69.9 nominal"}, "base_thickness": {"value": 12.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT/RIGHT bottom band proportion, no step dimension on drawing"}, "bolt_hole_diameter": {"value": 14.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP circles and FRONT/RIGHT dashed lines, scaled to views"}, "bolt_hole_end_offset": {"value": 28.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP circle centres scaled from each end of 140 mm flange"}, "pedestal_width": {"value": 88.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT stepped outline scaled against 140 mm overall length"}, "pedestal_step_height": {"value": 20.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT step below bearing bore, scaled against 70 mm height"}, "housing_width": {"value": 60.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT arch/housing outline scaled against 140 mm length"}, "housing_depth": {"value": 28.0, "unit": "mm", "provenance": "inferred", "evidence": "TOP/RIGHT single housing face line, rear-flush housing"}, "bore_diameter": {"value": 34.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT bore circle scaled against overall views"}, "bore_centre_height": {"value": 40.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT bore circle centre scaled against 70 mm height"}, "cap_outer_radius": {"value": 30.0, "unit": "mm", "provenance": "inferred", "evidence": "FRONT semicircular arch: bore centre plus radius reaches 70 mm top"}}
length = P("length")
width = P("width")
height = P("height")
baseThickness = P("base_thickness")
boltHoleDiameter = P("bolt_hole_diameter")
boltHoleEndOffset = P("bolt_hole_end_offset")
pedestalWidth = P("pedestal_width")
pedestalStepHeight = P("pedestal_step_height")
housingWidth = P("housing_width")
housingDepth = P("housing_depth")
boreDiameter = P("bore_diameter")
boreCentreHeight = P("bore_centre_height")
capOuterRadius = P("cap_outer_radius")
centreX = length / 2.0
rearY = -width / 2.0
grey = "#888c90"
baseSolid = cq.Solid.makeBox(length, width, baseThickness, cq.Vector(0, rearY, 0))
for holeX in (boltHoleEndOffset, length - boltHoleEndOffset):
    holeTool = cq.Solid.makeCylinder(boltHoleDiameter / 2.0, baseThickness + 4.0, cq.Vector(holeX, 0, -2.0), cq.Vector(0, 0, 1))
    baseSolid = baseSolid.cut(holeTool)
pedestalSolid = cq.Solid.makeBox(pedestalWidth, width, pedestalStepHeight - baseThickness, cq.Vector(centreX - pedestalWidth / 2.0, rearY, baseThickness))
lowerSolid = cq.Solid.makeBox(housingWidth, housingDepth, boreCentreHeight - pedestalStepHeight, cq.Vector(centreX - housingWidth / 2.0, rearY, pedestalStepHeight))
boreToolLower = cq.Solid.makeCylinder(boreDiameter / 2.0, housingDepth + 4.0, cq.Vector(centreX, rearY - 2.0, boreCentreHeight), cq.Vector(0, 1, 0))
lowerSolid = lowerSolid.cut(boreToolLower)
capCylinder = cq.Solid.makeCylinder(capOuterRadius, housingDepth, cq.Vector(centreX, rearY, boreCentreHeight), cq.Vector(0, 1, 0))
capBox = cq.Solid.makeBox(housingWidth, housingDepth, height - boreCentreHeight, cq.Vector(centreX - housingWidth / 2.0, rearY, boreCentreHeight))
capSolid = capCylinder.intersect(capBox)
boreToolCap = cq.Solid.makeCylinder(boreDiameter / 2.0, housingDepth + 4.0, cq.Vector(centreX, rearY - 2.0, boreCentreHeight), cq.Vector(0, 1, 0))
capSolid = capSolid.cut(boreToolCap)
parts = [{"name": "base_flange", "shape": baseSolid, "colour": grey, "material": "metal"}, {"name": "pedestal_block", "shape": pedestalSolid, "colour": grey, "material": "metal"}, {"name": "lower_bearing_housing", "shape": lowerSolid, "colour": grey, "material": "metal"}, {"name": "bearing_cap", "shape": capSolid, "colour": grey, "material": "metal"}]